  "clientScript": "import { Region } from '@portal/runtime'\n\n/** Header / sidebar / main / footer. Main takes all remaining space and is the only scroller. */\nexport default function StandardLayout() {\n    return (\n        <div className=\"rp-std\">\n            <header className=\"rp-std__header\">\n                <Region name=\"header\" />\n            </header>\n            <div className=\"rp-std__body\">\n                <aside className=\"rp-std__sidebar\">\n                    <Region name=\"sidebar\" />\n                </aside>\n                <main className=\"rp-std__main\">\n                    <Region name=\"main\" />\n                </main>\n            </div>\n            <footer className=\"rp-std__footer\">\n                <Region name=\"footer\" />\n            </footer>\n        </div>\n    )\n}\n",
  "css": "/* Fills the frame the host gives it; main takes all remaining space and is the only scroller. */\n.rp-std { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; height: 100%; width: 100%; min-height: 0; overflow: hidden; background: var(--background); color: var(--foreground); }\n.rp-std__header { border-bottom: 1px solid var(--border); }\n.rp-std__body { display: grid; grid-template-columns: auto minmax(0, 1fr); min-height: 0; }\n.rp-std__sidebar { width: 220px; overflow-y: auto; border-right: 1px solid var(--border); padding: 16px 12px; box-sizing: border-box; }\n.rp-std__main { min-width: 0; min-height: 0; overflow: auto; }\n.rp-std__main > [data-rp-region] { display: grid; gap: 16px; align-content: start; padding: 24px; min-height: 100%; box-sizing: border-box; }\n.rp-std__footer { border-top: 1px solid var(--border); padding: 12px 24px; color: var(--muted-foreground); font-size: 12px; }\n.rp-std__header:not(:has([data-rp-widget])), .rp-std__sidebar:not(:has([data-rp-widget])), .rp-std__footer:not(:has([data-rp-widget])) { display: none; }\n",
